import { Book } from "@/lib/types";

export const zechariah: Book = {
  id: "zechariah",
  name: "Sacharja",
  shortName: "Sach",
  testament: "old",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Im achten Monat, im zweiten Jahr des Darius*, geschah das Wort des HERRN zum Propheten Sacharja*, dem Sohn Berechjas, des Sohnes Iddos*:", heading: "Ruf zur Umkehr", footnotes: ["℘ Kap. 7,1; Hag 1,1", "℘ Esr 5,1", "℘ Neh 12,16"] },
      { number: 2, text: "Der HERR ist heftig erzürnt* gewesen über eure Väter*.", footnotes: ["w. erzürnt mit Zorn", "℘ Kap. 7,12; 8,14; 2Kö 22,17"] },
      { number: 3, text: "Und du sollst zu ihnen sagen: So spricht der HERR der Heerscharen: Kehrt um zu mir!, spricht der HERR* der Heerscharen, und ich werde mich zu euch umkehren*, spricht der HERR der Heerscharen.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ 2Chr 15,4; Mal 3,7; Lk 15,20; Jak 4,8"] },
      { number: 4, text: "Seid nicht wie eure Väter, denen die früheren Propheten zuriefen*: »So spricht der HERR der Heerscharen: Kehrt doch um von euren bösen Wegen und von euren bösen Taten!«* Aber sie hörten nicht und merkten nicht auf mich*, spricht der HERR*.", footnotes: ["℘ Kap. 7,7", "℘ Jer 3,12-14; Hes 14,6; 18,30", "℘ Kap. 7,11; 2Chr 30,6-9; Hes 33,4; Dan 9,6", "w. ist der Ausspruch des HERRN"] },
      { number: 5, text: "Eure Väter, wo sind sie? Und die Propheten, leben sie ewig*?", footnotes: ["℘ 1Sam 25,1; 2Kö 13,14.20; Joh 8,52"] },
      { number: 6, text: "Doch meine Worte und meine Vorhaben, die ich meinen Knechten, den Propheten*, gebot, haben sie eure Väter nicht erreicht*? Und sie kehrten um und sagten: Wie der HERR der Heerscharen vorhatte, nach unseren Wegen und nach unseren Taten an uns zu handeln, so hat er mit uns gehandelt*.", footnotes: ["℘ Offb 10,7", "℘ 2Chr 36,17-21; Jes 44,26; 55,11; Jer 32,24; 39,16; 44,2-6", "℘ Jer 23,20; Kla 1,18; 3,42; Dan 9,11.12; 2Petr 1,19"] },
      { number: 7, text: "Am 24. Tag, im elften Monat, das ist der Monat Schebat*, im zweiten Jahr des Darius, geschah das Wort des HERRN zum Propheten Sacharja, dem Sohn Berechjas, des Sohnes Iddos:", heading: "Erste Nachtvision: Reiter auf verschiedenfarbigen Pferden", footnotes: ["d. i. vom Neumond des Februar bis zum Neumond des März"] },
      { number: 8, text: "Ich schaute des Nachts*, und siehe, ein Mann, der auf einem roten Pferd ritt*! Und er hielt* zwischen den Myrten, die im Talgrund waren, und hinter ihm waren rote, hellrote und weiße* Pferde.", footnotes: ["℘ 1Mo 46,2; 4Mo 12,6", "℘ Kap. 6,2; Offb 6,4", "w. war stehen bleibend", "LXX ergänzt: und starke; vgl. 6,3.7"] },
      { number: 9, text: "Und ich sagte: Was bedeuten diese, mein Herr? Und der Engel, der mit mir redete, sprach zu mir: Ich selbst will dir zeigen, wer diese sind*.", footnotes: ["℘ Dan 8,15.16"] },
      { number: 10, text: "Und der Mann, der zwischen den Myrten hielt, antwortete und sprach: Das sind die, welche der HERR ausgesandt hat, auf Erden umherzuziehen*.", footnotes: ["℘ Kap. 5,7"] },
      { number: 11, text: "Und sie antworteten dem Engel des HERRN, der zwischen den Myrten hielt, und sprachen: Wir sind auf Erden umhergezogen*, und siehe, die ganze Erde sitzt still und verhält sich ruhig.", footnotes: ["℘ Hi 1,7"] },
      { number: 12, text: "Aber der Engel des HERRN antwortete und sprach: HERR der Heerscharen, wie lange willst du dich nicht über Jerusalem und die Städte Judas erbarmen*, die du verwünscht hast diese siebzig Jahre*?", footnotes: ["℘ Ps 79,5; Jes 64,11", "℘ Kap. 7,5; Jer 25,11"] },
      { number: 13, text: "Und der HERR antwortete dem Engel, der mit mir redete, gütige Worte, tröstliche Worte*.", footnotes: ["w. Worte von Tröstungen\n℘ Jes 40,1.2; 2Kor 1,3.4"] },
      { number: 14, text: "Und der Engel, der mit mir redete, sprach zu mir: Rufe aus: So spricht der HERR der Heerscharen: Ich eifere* mit großem Eifer für Jerusalem und für Zion*,", footnotes: ["d. h. hier: Ich verteidige das Recht; so auch Kap. 8,2", "℘ Kap. 8,2; Jes 59,17; Hes 36,5; Joe 2,18"] },
      { number: 15, text: "und mit großem Zorn zürne ich über die sicheren* Nationen*. Sie, nämlich als ich nur wenig* zürnte, da haben sie zum Unheil geholfen*.", footnotes: ["o. selbstsicheren; o. sorglosen; o. stolzen", "℘ Hab 3,12", "o. eine kleine Weile", "℘ Jes 47,6; Jer 30,16; 50,33"] },
      { number: 16, text: "Darum, so spricht der HERR: Ich habe mich Jerusalem in Erbarmen wieder zugewandt*. Mein Haus soll darin gebaut werden*, spricht der HERR* der Heerscharen, und die Messschnur soll über Jerusalem ausgespannt werden*.", footnotes: ["℘ Kap. 8,3; Jes 12,1; Jer 30,18", "℘ Esr 6,14", "w. ist der Ausspruch des HERRN", "℘ Kap. 2,5.6"] },
      { number: 17, text: "Rufe weiter aus: So spricht der HERR der Heerscharen: Meine Städte sollen noch überfließen von Gutem*; und der HERR wird Zion noch trösten* und Jerusalem noch erwählen*.", footnotes: ["℘ Jer 33,9", "LXX: wird sich noch erbarmen über Zion\n℘ Jes 40,1.2; 2Kor 1,3.4", "℘ Kap. 2,16; 3,2; Jes 14,1"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "Und ich hob meine Augen auf und sah: Und siehe, vier Hörner*!", heading: "Zweite Nachtvision: Hörner und Handwerker", footnotes: ["℘ Dan 7,7"] },
      { number: 2, text: "Und ich sagte zu dem Engel, der mit mir redete: Was sind diese? Und er sprach zu mir: Das sind die Hörner, die Juda, Israel und Jerusalem zerstreut* haben.", footnotes: ["w. geworfelt; d. h. wie Getreide bei der Reinigung nach dem Dreschen"] },
      { number: 3, text: "Und der HERR ließ mich vier Handwerker sehen." },
      { number: 4, text: "Und ich sagte: Was wollen diese tun? Und er sprach: Das sind die Hörner, die Juda derartig zerstreut haben, dass niemand mehr sein Haupt erhob; und diese sind gekommen, um sie in Schrecken zu setzen* und um die Hörner der Nationen niederzuwerfen*, die ein Horn gegen das Land Juda erhoben haben, um es zu zerstreuen*.", footnotes: ["LXX: zu erbittern", "℘ Ps 75,11", "℘ Kap. 14,12; Jes 54,16"] },
      { number: 5, text: "Und ich hob meine Augen auf und sah: Und siehe, ein Mann, der hatte in seiner Hand eine Messschnur*.", heading: "Dritte Nachtvision: Der Mann mit der Messschnur", footnotes: ["℘ Hes 47,3"] },
      { number: 6, text: "Und ich sagte: Wohin gehst du? Und er sprach zu mir: Jerusalem zu messen*, um zu sehen, wie groß seine Breite und wie groß seine Länge ist*.", footnotes: ["℘ Kap. 1,16; Offb 21,15", "℘ Jer 31,38-40"] },
      { number: 7, text: "Und siehe, als der Engel, der mit mir redete, herausging*, da ging ein anderer Engel heraus, ihm entgegen.", footnotes: ["LXX: stehen blieb"] },
      { number: 8, text: "Und er sprach zu ihm: Lauf, rede zu diesem jungen Mann: Eine offene Stadt* wird Jerusalem bleiben* wegen der Menge an Menschen und Vieh in seiner Mitte*.", footnotes: ["w. offenes Land; d. h. ohne Befestigungsmauer", "o. Als eine offene Stadt wird Jerusalem bewohnt werden o. daliegen", "℘ Kap. 8,5; Jes 49,19; Hes 38,11"] },
      { number: 9, text: "Und ich selbst werde ihm ringsherum eine feurige Mauer sein*, spricht der HERR*, und ich werde zur Herrlichkeit in seiner Mitte sein*.", footnotes: ["℘ Kap. 9,15; Jes 4,5; 26,1; Offb 21,12", "w. ist der Ausspruch des HERRN", "℘ Jes 12,6; 60,19; Jer 8,19; Joe 2,27; Zef 3,15.17"] },
      { number: 10, text: "Wehe! Wehe! Flieht aus dem Land des Nordens*!, spricht der HERR*. Denn nach den vier Winden des Himmels habe ich euch ausgebreitet*, spricht der HERR*.", heading: "Heilsverheißungen", footnotes: ["℘ Jes 48,20", "w. ist der Ausspruch des HERRN", "o. zerstreut. — LXX: von den vier Winden habe ich euch eingesammelt\n℘ 5Mo 28,64; Mt 24,31", "o. zerstreut. — LXX: von den vier Winden habe ich euch eingesammelt"] },
      { number: 11, text: "Wehe! Zion, rette dich, die du wohnst bei der Tochter Babels!*", footnotes: ["℘ Jes 52,11; Jer 50,8"] },
      { number: 12, text: "Denn so spricht der HERR der Heerscharen, nachdem die Herrlichkeit* mich ausgesandt hat, über die Nationen, die euch geplündert haben* — denn wer euch antastet, tastet seinen* Augapfel an* —:", footnotes: ["»die Herrlichkeit« ist viell. eine Bezeichnung für Gott selbst", "℘ Jes 17,14; Jer 30,16", "Die alten Abschreiber merken hier an, dass sie den Text geändert haben. Der ursprüngliche Text lautete: meinen", "℘ Est 6,13\no. so spricht der HERR der Heerscharen — mit Herrlichkeit hat er mich zu den Nationen gesandt, die euch geplündert haben —: Ja, wer euch antastet, tastet seinen eigenen Augapfel an!"] },
      { number: 13, text: "Ja, siehe, ich werde meine Hand über sie schwingen*, und sie sollen ihren Knechten* zur Beute werden. Und ihr werdet erkennen, dass der HERR der Heerscharen mich gesandt hat*.", footnotes: ["o. schütteln\n℘ Jes 19,16", "℘ Jes 14,2; Zef 2,9", "℘ Kap. 4,9; 6,15; 5Mo 18,21.22"] },
      { number: 14, text: "Juble und freue dich, Tochter Zion! Denn siehe, ich komme* und werde in deiner Mitte wohnen*, spricht der HERR*.", footnotes: ["℘ Kap. 9,9; Jes 40,10; Offb 22,20", "℘ Kap. 8,3; Zef 3,14.15; 2Kor 6,16", "w. ist der Ausspruch des HERRN"] },
      { number: 15, text: "Und an jenem Tag werden viele Nationen sich dem HERRN anschließen*. So werden sie mein Volk sein. Und ich werde in deiner Mitte wohnen*, und du wirst erkennen, dass der HERR der Heerscharen mich zu dir gesandt hat*.", footnotes: ["℘ Kap. 8,20-23; Est 9,27", "℘ Kap. 4,9; 6,15; 5Mo 18,21.22", "℘ Kap. 4,9; 6,15; 5Mo 18,21.22"] },
      { number: 16, text: "Und der HERR wird Juda als sein Erbteil besitzen* im heiligen Land und wird Jerusalem aufs Neue erwählen*.", footnotes: ["o. in Besitz nehmen\n℘ 5Mo 32,9", "℘ Kap. 1,17; Jer 51,5"] },
      { number: 17, text: "Alles Fleisch schweige* vor dem HERRN*! Denn er hat sich aufgemacht aus seiner heiligen Wohnung*.", footnotes: ["w. Still, alles Fleisch,", "℘ Jes 41,1; Hab 2,20", "℘ Jes 26,21; Jer 25,30"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Und er ließ mich den Hohenpriester Joschua* sehen, der vor dem Engel des HERRN stand; und der Satan stand zu seiner Rechten, um ihn anzuklagen*.", heading: "Vierte Nachtvision: Der Hohepriester Joschua", footnotes: ["hebr. jehoschua; d. h. der HERR ist Rettung\n℘ Hag 1,1", "o. ihm zu widerstehen; Wortspiel zu Satan = Ankläger, Widersacher\n℘ Offb 12,10"] },
      { number: 2, text: "Und der HERR* sprach zum Satan: Der HERR wird dich bedrohen*, Satan*! Ja, der HERR, der Jerusalem erwählt hat*, bedroht dich*! Ist dieser nicht ein Holzscheit, das aus dem Feuer herausgerissen ist*?", footnotes: ["syr. Üs.: Der Engel des HERRN", "w. wird dich anschreien", "℘ Jud 9", "℘ Kap. 1,17; 2Chr 6,6", "w. schreit dich an", "℘ Am 4,11"] },
      { number: 3, text: "Und Joschua war mit schmutzigen Kleidern bekleidet* und stand vor dem Engel.", footnotes: ["℘ Jes 64,5"] },
      { number: 4, text: "Und der Engel* antwortete und sprach zu denen, die vor ihm standen: Nehmt ihm die schmutzigen Kleider ab! Und zu ihm sprach er: Siehe, ich habe deine Schuld von dir weggenommen* und bekleide dich mit Feierkleidern*.", footnotes: ["so mit der syr. Üs.; Mas. T.: er", "℘ Jes 6,7; 44,22", "℘ Lk 15,22"] },
      { number: 5, text: "Und ich* sprach: Man setze einen reinen Kopfbund auf sein Haupt*! Und sie setzten den reinen Kopfbund auf sein Haupt und zogen ihm reine Kleider an*; und der Engel des HERRN stand dabei.", footnotes: ["syr. und lat. Üs. lesen: Und er", "℘ Kap. 6,11; 2Mo 29,6", "℘ Jes 61,10"] },
      { number: 6, text: "Und der Engel des HERRN bezeugte* dem Joschua:", footnotes: ["o. versicherte feierlich"] },
      { number: 7, text: "So spricht der HERR der Heerscharen: Wenn du auf meinen Wegen gehen und wenn du meine Anordnungen befolgen wirst*, dann sollst du sowohl mein Haus richten* als auch meine Vorhöfe beaufsichtigen*; und ich werde dir Zutritt geben unter* diesen, die hier stehen.", footnotes: ["℘ Hes 44,15", "o. verwalten", "w. bewachen", "w. zwischen diesen hindurch; d. h. es wird unmittelbarer Zugang zum HERRN gewährt"] },
      { number: 8, text: "Höre doch, Joschua, du, der Hohepriester, du und deine Gefährten, die vor dir sitzen — denn Männer des Wunders* sind sie*! Ja, siehe, ich will meinen Knecht*, Spross genannt*, kommen lassen.", footnotes: ["o. des Wahrzeichens; o. des Vorbildes", "℘ Jes 8,18; Hes 12,6.11", "℘ Jes 42,1", "℘ Kap. 6,12; Jes 4,2; Jer 23,5"] },
      { number: 9, text: "Denn siehe, der Stein*, den ich vor Joschua gelegt habe — auf einem Stein sieben Augen* —, siehe, ich will seine Gravur eingravieren, spricht der HERR* der Heerscharen, und will die Schuld dieses Landes entfernen an einem Tag*.", footnotes: ["℘ Jes 28,16", "℘ Kap. 4,10; Offb 5,6", "w. ist der Ausspruch des HERRN", "℘ Jer 50,20; Mk 2,5.7; Joh 1,29"] },
      { number: 10, text: "An jenem Tag, spricht der HERR* der Heerscharen, werdet ihr einer den anderen einladen unter den Weinstock und unter den Feigenbaum*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ 1Kö 5,5"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Und der Engel, der mit mir redete, kam wieder und weckte mich wie einen Mann, der aus seinem Schlaf geweckt wird*.", heading: "Fünfte Nachtvision: Der Leuchter aus Gold und die beiden Ölbäume", footnotes: ["℘ Jer 31,26; Dan 8,18"] },
      { number: 2, text: "Und er sprach zu mir: Was siehst du*? Und ich sagte: Ich sehe: und siehe, ein Leuchter ganz aus Gold und sein Ölgefäß oben auf ihm* und seine sieben Lampen auf ihm, je sieben* Gießröhren für die Lampen, die oben auf ihm* sind*;", footnotes: ["℘ Kap. 5,2; Am 7,8", "w. auf seinem Haupt", "w. sieben und sieben", "w. sieben und sieben", "℘ 2Mo 25,31; Offb 1,12; 4,5"] },
      { number: 3, text: "und zwei Ölbäume neben ihm, einer zur Rechten des Ölgefäßes und einer auf seiner Linken." },
      { number: 4, text: "Ich antwortete und sagte zu dem Engel, der mit mir redete: Was sind diese, mein Herr?" },
      { number: 5, text: "Und der Engel, der mit mir redete, antwortete und sprach zu mir: Hast du nicht erkannt, was diese sind? Und ich sagte: Nein, mein Herr." },
      { number: 6, text: "Da antwortete er und sprach zu mir: Dies ist das Wort des HERRN an Serubbabel*: Nicht durch Macht und nicht durch Kraft*, sondern durch meinen Geist*, spricht der HERR der Heerscharen.", footnotes: ["℘ Esr 2,2", "d. h. durch Heeresmacht und Menschentüchtigkeit\n℘ Hos 1,7", "℘ 1Kö 19,12; Jes 34,16; 59,19; Hag 2,5"] },
      { number: 7, text: "Wer bist du, großer Berg? Vor Serubbabel werde zur Ebene*! Und er wird den Schlussstein* herausbringen unter lautem Zuruf: Gnade, Gnade für ihn!", footnotes: ["℘ Jes 40,4", "o. Giebelstein"] },
      { number: 8, text: "Und das Wort des HERRN geschah zu mir:" },
      { number: 9, text: "Die Hände Serubbabels haben die Grundmauern dieses Hauses gelegt, und seine Hände werden es vollenden*. Und du wirst erkennen, dass der HERR der Heerscharen mich zu euch gesandt hat*.", footnotes: ["℘ Esr 3,8; 6,15", "℘ Kap. 2,13.15"] },
      { number: 10, text: "Denn wer hat den Tag kleiner Dinge* verachtet*? Und sie werden sich freuen und den Stein des Senkbleis* in der Hand Serubbabels sehen. *Diese sieben sind die Augen des HERRN, sie schweifen auf der ganzen Erde umher*.", footnotes: ["o. Anfänge", "℘ Hag 2,3", "viell. der Schlussstein (vgl. V. 7), der so heißt, weil die Inschrift, die er tragen soll, mit Blei ausgegossen wird; andere üs.: Stein der Aussonderung", "Dieser Satz knüpft sachlich an V. 1—6a an: Da antwortete er und sprach zu mir . . .: Diese sieben sind die", "℘ Kap. 3,9; 9,1; 2Chr 16,9; Offb 5,6"] },
      { number: 11, text: "Und ich antwortete und sagte zu ihm: Was sind diese zwei Ölbäume zur Rechten des Leuchters und zu seiner Linken?" },
      { number: 12, text: "Und ich antwortete zum zweiten Mal und sagte zu ihm: Was sind die beiden Zweigbüschel* der Ölbäume, die neben den zwei goldenen Röhren sind, die das Goldöl von sich ausfließen lassen*?", footnotes: ["w. Ähren", "w. ausgießen"] },
      { number: 13, text: "Und er sprach zu mir: Hast du nicht erkannt, was diese sind? Und ich sagte: Nein, mein Herr." },
      { number: 14, text: "Da sprach er: Dies sind die beiden Gesalbten*, die bei dem Herrn der ganzen Erde* stehen*.", footnotes: ["w. Söhne des Öls\n℘ Esr 5,2", "℘ Jos 3,11.13", "℘ Kap. 6,5; Offb 11,3.4"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "Und ich hob wieder meine Augen auf und sah: Und siehe, eine fliegende Schriftrolle!", heading: "Sechste Nachtvision: Die fliegende Schriftrolle" },
      { number: 2, text: "Und er sprach zu mir: Was siehst du*? Und ich sagte: Ich sehe eine fliegende Schriftrolle, ihre Länge beträgt zwanzig Ellen und ihre Breite zehn Ellen.", footnotes: ["℘ Kap. 4,2"] },
      { number: 3, text: "Und er sprach zu mir: Dies ist der Fluch, der ausgeht über die Fläche des ganzen Landes*. Denn jeder, der stiehlt, ist bisher — wie lange nun schon! — ungestraft geblieben, und jeder, der falsch schwört, ist bisher — wie lange nun schon! — ungestraft geblieben.*", footnotes: ["o. der ganzen Erde", "T.; andere üs. mit anderer Wortabtrennung: Denn jeder, der stiehlt, wie sollte der — dem Fluch entsprechend — ungestraft bleiben? Und jeder, der falsch schwört, wie sollte der — dem Fluch entsprechend — ungestraft bleiben? Mas. T.: Denn jeder, der stiehlt, ist bisher — dem Fluch entsprechend — ungestraft geblieben, und jeder, der falsch schwört, ist bisher — dem Fluch entsprechend — ungestraft geblieben.\n℘ Kap. 8,17; 3Mo 19,11.12; Hes 2,9.10"] },
      { number: 4, text: "Ich habe ihn* ausgehen lassen, spricht der HERR* der Heerscharen, und er wird kommen in das Haus des Diebes und in das Haus dessen, der bei meinem Namen falsch schwört*; und mitten in seinem Haus wird er über Nacht bleiben* und wird es vernichten, sowohl sein Gebälk als auch seine Steine*.", footnotes: ["d. h. den Fluch", "w. ist der Ausspruch des HERRN", "℘ Jos 9,20; Mal 3,5", "℘ 5Mo 28,16; Spr 3,33", "℘ Hi 8,22"] },
      { number: 5, text: "Und der Engel, der mit mir redete, trat hervor und sprach zu mir: Heb doch deine Augen auf und sieh! Was ist dies da, das da hervorkommt?", heading: "Siebte Nachtvision: Die Frau im Efa" },
      { number: 6, text: "Ich sagte: Was ist es? Und er sprach: Dies ist das Efa*, das hervorkommt. Und er sprach: Das ist ihr Aussehen* im ganzen Land*.", footnotes: ["Efa ist ein Hohlmaß; die heutige Bestimmung des Fassungsvermögens schwankt zwischen 22 und 40 l", "w. ihr Auge. — LXX und die syr. Üs.: ihre Schuld", "℘ Am 8,4-6; Mi 6,10-12"] },
      { number: 7, text: "Und siehe, ein runder Bleideckel hob sich; und da war eine Frau, die saß mitten im Efa*.", footnotes: ["Efa ist ein Hohlmaß; die heutige Bestimmung des Fassungsvermögens schwankt zwischen 22 und 40 l"] },
      { number: 8, text: "Und er sprach: Dies ist die Gottlosigkeit. Und er warf sie wieder mitten in das Efa* hinein und warf den Bleideckel auf dessen Öffnung.", footnotes: ["Efa ist ein Hohlmaß; die heutige Bestimmung des Fassungsvermögens schwankt zwischen 22 und 40 l"] },
      { number: 9, text: "Und ich hob meine Augen auf und sah: Und siehe, da kamen zwei Frauen hervor, und Wind war in ihren Flügeln, und sie hatten Flügel wie Flügel des Storches; und sie hoben das Efa* empor zwischen die Erde und den Himmel.", footnotes: ["Efa ist ein Hohlmaß; die heutige Bestimmung des Fassungsvermögens schwankt zwischen 22 und 40 l"] },
      { number: 10, text: "Und ich sagte zu dem Engel, der mit mir redete: Wohin bringen diese das Efa*?", footnotes: ["Efa ist ein Hohlmaß; die heutige Bestimmung des Fassungsvermögens schwankt zwischen 22 und 40 l"] },
      { number: 11, text: "Und er sprach zu mir: Um ihm* ein Haus zu bauen im Land Schinar*. Und ist dieses aufgestellt, wird das Efa* auf seine Stelle hingestellt.", footnotes: ["Formal ist das Efa gemeint, sachlich die Frau in ihm.", "℘ 1Mo 10,10; 11,2; Dan 1,2", "w. es"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "Und ich hob wieder* meine Augen auf und sah: Und siehe, vier Wagen*, die zwischen den zwei Bergen hervorkamen! Und die Berge waren Berge aus Bronze.", heading: "Achte Nachtvision: Die vier Wagen", footnotes: ["w. wendete mich und hob", "℘ Jes 66,15; Jer 4,13"] },
      { number: 2, text: "Am ersten Wagen waren rote Pferde* und am zweiten Wagen schwarze Pferde", footnotes: ["℘ Kap. 1,8"] },
      { number: 3, text: "und am dritten Wagen weiße Pferde und am vierten Wagen scheckige, starke Pferde*.", footnotes: ["℘ Offb 6,2-8"] },
      { number: 4, text: "Und ich antwortete und sagte zu dem Engel, der mit mir redete: Was sind diese, mein Herr?" },
      { number: 5, text: "Und der Engel antwortete und sprach zu mir: »Diese sind die vier Winde* des Himmels*, die herauskommen, nachdem sie vor dem Herrn der ganzen Erde gestanden haben*.", footnotes: ["o. Geister", "℘ Ps 104,4; Offb 7,1", "℘ Kap. 4,14"] },
      { number: 6, text: "Die schwarzen Pferde, die daran sind, ziehen aus ins Land des Nordens; und die weißen ziehen aus hinter ihnen her; und die scheckigen ziehen aus ins Land des Südens*;", footnotes: ["℘ Jes 30,6; Dan 11,5"] },
      { number: 7, text: "*und die starken ziehen aus*.« Und sie trachteten danach* hinauszugehen, um auf Erden umherzuziehen. Und er sprach: Geht, zieht umher auf Erden! Da zogen sie auf Erden umher*.", footnotes: ["o. Als nun die starken ausgezogen waren, trachteten sie danach", "eine LXX-Ausgabe: ziehen aus ins Land des Südens", "eine LXX-Ausgabe: ziehen aus ins Land des Südens", "℘ Kap. 1,10"] },
      { number: 8, text: "Und er rief mich an und redete zu mir: Siehe, die, welche ins Land des Nordens ausgezogen sind*, lassen meinen Geist Ruhe finden* im Land des Nordens.", footnotes: ["o. ausziehen", "d. h. stillen meinen Zorn"] },
      { number: 9, text: "Und das Wort des HERRN geschah zu mir:", heading: "Symbolische Krönung des Joschua" },
      { number: 10, text: "Nimm Gaben* von den Weggeführten, von Heldai und von Tobija und von Jedaja! Und geh du an diesem Tag, geh in das Haus Josias, des Sohnes Zefanjas*, wohin sie aus Babel gekommen sind!", footnotes: ["w. Es gibt etwas zu holen", "℘ 2Kö 25,18"] },
      { number: 11, text: "Und nimm Silber und Gold und mach eine Krone*! Und setze sie auf das Haupt des Hohenpriesters Joschua*, des Sohnes Jozadaks!", footnotes: ["so LXX und einige hebr. Handschr.; Mas. T. liest einen Ortsnamen", "℘ Kap. 3,5; Hebr 5,10"] },
      { number: 12, text: "Und sage ihm: So spricht der HERR der Heerscharen: Siehe, ein Mann, Spross ist sein Name*! Und es wird unter ihm sprossen*, und er wird den Tempel des HERRN* bauen*.", footnotes: ["℘ Kap. 3,8; Jes 4,2; 53,2", "o. an seiner Stelle (w. von unter sich selbst) wird er sprossen", "℘ Hes 41", "℘ 2Sam 7,13"] },
      { number: 13, text: "Ja, er wird den Tempel des HERRN* bauen*, und er wird Hoheit tragen* und wird auf seinem Thron sitzen und herrschen. Auch wird ein Priester auf seinem Thron* sein*; und der Rat des Friedens wird zwischen ihnen beiden sein.", footnotes: ["℘ 2Sam 7,13", "℘ 2Sam 7,13", "℘ Ps 21,4.6; Jes 9,5", "o. neben seinem Thron. — LXX: zu seiner Rechten", "℘ Ps 110,1.4; Hebr 3,3; 10,21"] },
      { number: 14, text: "Und die Krone* soll dem Heldai, dem Tobija und Jedaja und der Gnade des Sohnes Zefanjas im Tempel des HERRN zur Erinnerung sein.", footnotes: ["so LXX und einige hebr. Handschr.; Mas. T. liest einen Ortsnamen"] },
      { number: 15, text: "Und Ferne werden kommen* und am Tempel des HERRN bauen. Und ihr werdet erkennen, dass der HERR der Heerscharen mich zu euch gesandt hat*. Und das wird geschehen, wenn ihr aufmerksam auf die Stimme des HERRN, eures Gottes, hören werdet*.", footnotes: ["℘ Jes 49,12; 60,10", "℘ Kap. 2,13.15", "℘ 5Mo 30,10"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "Und es geschah im vierten Jahr des Königs Darius*: Da geschah das Wort des HERRN zu Sacharja am vierten Tag des neunten Monats, im Monat Kislew*,", heading: "Die Frage nach dem Fasten und Gottes Antwort", footnotes: ["℘ Kap. 1,1", "℘ Neh 1,1"] },
      { number: 2, text: "als nämlich Bethel* den Sarezer und Regem-Melech und seine Männer sandte, um den HERRN* anzuflehen*", footnotes: ["d. h. die Einwohnerschaft von Bethel; o. da sandte Bethel — Sarezer den Regem-Melech und seine Männer\n℘ Esr 2,28", "w. das Angesicht des HERRN", "o. zu besänftigen"] },
      { number: 3, text: "und um die Priester*, die zum Hause des HERRN der Heerscharen gehörten, und die Propheten zu fragen: Soll ich weinen im fünften Monat* beim Fasten*, wie ich es schon so viele Jahre getan habe?", footnotes: ["℘ 5Mo 17,9; Mal 2,7", "℘ Kap. 8,19", "w. wobei ich mich der Nahrung enthielt; die Juden hatten während der Babylonischen Gefangenschaft den Brauch eingeführt, zum Gedenken an die Hauptdaten der Belagerung und Eroberung von Jerusalem Fastentage abzuhalten, und zwar im 4., 5., 7. und 10. Monat; vgl. V. 5 und Kap. 8,19"] },
      { number: 4, text: "Und das Wort des HERRN der Heerscharen geschah zu mir:" },
      { number: 5, text: "Sprich zum ganzen Volk des Landes und zu den Priestern: Wenn ihr im fünften* und im siebten Monat* beim Wehklagen gefastet habt, und dies siebzig Jahre*, habt ihr etwa mir gefastet*?", footnotes: ["℘ Kap. 8,19", "℘ 2Kö 25,25", "℘ Kap. 1,12", "℘ Jes 58,3.4"] },
      { number: 6, text: "Und wenn ihr esst und wenn ihr trinkt, seid ihr es nicht, die da essen, nicht ihr, die da trinken*?", footnotes: ["℘ Röm 14,17; 1Kor 10,31"] },
      { number: 7, text: "Sind es nicht die Worte, die der HERR durch die früheren Propheten in den Tagen ausrief*, als Jerusalem bewohnt und ruhig war und seine Städte rings um es her und der Süden und die Niederung* bewohnt waren?", footnotes: ["℘ Kap. 1,4", "hebr. Schefelah; d. i. der Küstenstreifen zwischen Jafa und Gaza"] },
      { number: 8, text: "Und das Wort des HERRN geschah zu Sacharja:" },
      { number: 9, text: "So spricht der HERR der Heerscharen: Fällt zuverlässigen Rechtsspruch* und erweist Güte* und Barmherzigkeit einer dem anderen*!", footnotes: ["w. Richtet einen Rechtsspruch\n℘ Ps 82,3.4", "o. Gnade; o. Treue", "w. ein Mann seinem Bruder\n℘ Jes 58,6.7; Hos 12,7; Mi 6,8; Mt 23,23"] },
      { number: 10, text: "Und bedrückt nicht die Witwe und die Waise, den Fremden und den Elenden*! Und ersinnt nicht gegeneinander* Unglück in euren Herzen*!", footnotes: ["o. Besitzlosen\n℘ 2Mo 22,21; Spr 22,22; Jer 5,28", "w. ein Mann gegen seinen Bruder", "℘ Kap. 8,17; Spr 3,29; Mi 2,1"] },
      { number: 11, text: "Aber sie weigerten sich aufzumerken und zuckten widerspenstig die Schulter* und machten ihre Ohren schwerhörig, um nicht zu hören*.", footnotes: ["℘ Jer 6,17; Hos 4,16", "w. machten ihre Ohren schwer, weg vom Hören\n℘ Kap. 1,4; Jes 28,12; Jer 7,24; 42,21"] },
      { number: 12, text: "Und sie machten ihr Herz zu Diamant*, um die Weisung nicht zu hören, noch die Worte, die der HERR der Heerscharen durch seinen Geist sandte durch die früheren Propheten*; so kam ein großer Zorn auf beim* HERRN der Heerscharen*.", footnotes: ["℘ 2Mo 7,13.22; Jer 5,3; Mt 19,8; Hebr 3,8", "℘ Jer 17,23; 42,21", "w. wurde ein großer Zorn vonseiten des", "℘ Kap. 1,2; Jes 65,12; Jer 7,20"] },
      { number: 13, text: "Und es geschah: Wie er gerufen und sie nicht gehört hatten, so werden sie rufen, und ich werde nicht hören*, spricht der HERR der Heerscharen.", footnotes: ["℘ Jer 14,12"] },
      { number: 14, text: "Und ich verwehte sie über all die Nationen hin, die sie nicht kannten, und das Land wurde hinter ihnen verödet*, so dass niemand hindurchzieht und zurückkommt. Und sie machten ein kostbares* Land zur schaurigen Öde.", footnotes: ["℘ 2Chr 36,21; Hes 12,19", "o. begehrenswertes"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "Und es geschah das Wort des HERRN der Heerscharen:", heading: "Verheißung der Rettung für Israel und die Völker" },
      { number: 2, text: "So spricht der HERR der Heerscharen: Ich eifere für Zion mit großem Eifer*, und mit großem Zorn eifere ich dafür*.", footnotes: ["s. Anm. zu Kap. 1,14", "℘ Kap. 1,14; 1Chr 12,19"] },
      { number: 3, text: "So spricht der HERR: Ich kehre nach Zion zurück* und wohne mitten in Jerusalem*. Und Jerusalem wird »Stadt der Treue*«* genannt werden und der Berg des HERRN der Heerscharen »heiliger Berg«*.", footnotes: ["℘ Kap. 1,16", "℘ Kap. 2,14.15; 2Mo 29,45.46; Hes 48,35", "o. Wahrheit", "℘ Jes 1,26", "℘ Kap. 14,10.20.21; Ps 2,6; Jes 11,9; Joe 4,17"] },
      { number: 4, text: "So spricht der HERR der Heerscharen: Noch werden Greise und Greisinnen auf den Plätzen von Jerusalem sitzen, jeder seinen Stab in seiner Hand wegen der Fülle der Tage*.", footnotes: ["d. h. wegen des hohen Alters\n℘ Jes 65,20"] },
      { number: 5, text: "Und die Plätze der Stadt werden voll von Jungen und Mädchen sein, die auf ihren Plätzen spielen*.", footnotes: ["℘ Kap. 2,8; Jer 30,19"] },
      { number: 6, text: "So spricht der HERR der Heerscharen: Wenn das zu wunderbar ist in den Augen des Restes dieses Volkes in jenen Tagen, sollte es auch in meinen Augen zu wunderbar sein*?, spricht der HERR* der Heerscharen.", footnotes: ["℘ Mt 19,26", "w. ist der Ausspruch des HERRN"] },
      { number: 7, text: "So spricht der HERR der Heerscharen: Siehe, ich werde mein Volk retten aus dem Land des Aufgangs und aus dem Land des Untergangs der Sonne*;", footnotes: ["℘ Neh 1,9; Ps 147,2; Jes 11,11.12; Hes 11,17; Mt 24,31"] },
      { number: 8, text: "und ich werde sie zurückbringen, und sie werden mitten in Jerusalem wohnen*. Und sie werden mein Volk und ich werde ihr Gott sein* in Treue* und in Gerechtigkeit*.", footnotes: ["℘ Hes 36,33", "℘ Kap. 13,9; 1Mo 17,8; Jer 30,22; Hos 11,11; 2Kor 6,16; Offb 21,7", "o. Wahrheit", "℘ Hos 2,21.22"] },
      { number: 9, text: "So spricht der HERR der Heerscharen: Eure Hände seien stark*, die ihr in diesen Tagen diese Worte aus dem Mund der Propheten hört, *die zu der Zeit wirkten*, als die Grundmauern des Hauses des HERRN der Heerscharen gelegt wurden, damit der Tempel erbaut werde*!", footnotes: ["℘ 2Chr 15,7; Jes 35,3; Hag 2,4", "o. an dem Tag", "o. an dem Tag", "℘ Esr 5,1.2"] },
      { number: 10, text: "Denn vor diesen Tagen war kein Lohn für den Menschen, und Lohn für das Vieh gab es nicht*. Und wer aus- und einging, hatte keinen Frieden vor dem Bedränger, und ich ließ alle Menschen gegeneinander los*.", footnotes: ["℘ Hag 1,6.9-11", "℘ 2Chr 15,5"] },
      { number: 11, text: "Nun aber will ich für den Rest dieses Volkes nicht wie in den früheren Tagen sein*, spricht der HERR* der Heerscharen,", footnotes: ["℘ Hag 2,15.19", "w. ist der Ausspruch des HERRN"] },
      { number: 12, text: "sondern die Saat des Friedens*, der Weinstock, wird seine Frucht geben, und die Erde wird ihren Ertrag geben, und der Himmel wird seinen Tau* geben*; und den Rest dieses Volkes werde ich all das erben lassen*.", footnotes: ["LXX: sondern ich will Frieden säen", "o. Regen", "℘ 5Mo 33,28; Ps 67,7; Jer 31,12; Hes 34,26.27; 36,9; Joe 2,19", "℘ Zef 3,13; Mal 3,11"] },
      { number: 13, text: "Und es wird geschehen: Wie ihr ein Fluch unter den Nationen gewesen seid*, Haus Juda und Haus Israel, so werde ich euch retten, und ihr werdet ein Segen sein*. Fürchtet euch nicht! Eure Hände seien stark*!", footnotes: ["℘ Ps 79,4; Jer 29,18", "℘ 1Mo 12,2; Jes 19,24; Hes 34,26; Zef 3,20", "℘ Zef 3,16"] },
      { number: 14, text: "Denn so spricht der HERR der Heerscharen: Ebenso wie ich mir vorgenommen hatte, euch Böses zu tun, als eure Väter mich zum Zorn reizten*, spricht der HERR der Heerscharen, und ich es mir nicht leid tun ließ,", footnotes: ["℘ Kap. 1,2"] },
      { number: 15, text: "so habe ich mir wieder vorgenommen, in diesen Tagen Jerusalem und dem Haus Juda Gutes zu tun*. Fürchtet euch nicht*!", footnotes: ["o. es glücklich zu machen\n℘ Jer 29,11; 31,28", "℘ Hag 2,5"] },
      { number: 16, text: "Dies sind die Dinge, die ihr tun sollt: Redet nur die Wahrheit einer mit dem anderen*! Fällt zuverlässigen und heilsamen Rechtsspruch* in euren Toren*!", footnotes: ["℘ Eph 4,25", "w. Zuverlässiges (o. Wahrheit) und Rechtsspruch des Heils (o. Friedens) richtet", "℘ Ps 34,15; Hes 18,8"] },
      { number: 17, text: "Und sinnt nicht — keiner von euch — in euren Herzen auf das Unglück des anderen*, und falschen Eid liebt nicht! Denn all dieses ist es, was ich hasse*, spricht der HERR*.", footnotes: ["℘ Kap. 7,10; Spr 6,18", "℘ Kap. 5,3; Ps 101,3", "w. ist der Ausspruch des HERRN"] },
      { number: 18, text: "Und das Wort des HERRN der Heerscharen geschah zu mir:" },
      { number: 19, text: "So spricht der HERR der Heerscharen: Das Fasten des vierten und das Fasten des fünften und das Fasten des siebten und das Fasten des zehnten Monats* wird dem Haus Juda zum Jubel und zur Freude und zu fröhlichen Festzeiten werden*. Doch die Wahrheit* und den Frieden liebt*!", footnotes: ["℘ Kap. 7,3.5; 2Kö 25,1.3.8.25; Jer 52,6; Hes 24,1", "℘ Est 9,22; Jer 31,13", "o. Treue", "℘ Ps 34,15; Hes 18,8"] },
      { number: 20, text: "So spricht der HERR der Heerscharen: Noch werden Völker und Bewohner vieler Städte kommen;" },
      { number: 21, text: "und die Bewohner der einen werden zur anderen gehen und sagen: Lasst uns doch hingehen, den HERRN um Gnade anzuflehen* und den HERRN der Heerscharen zu suchen! Auch ich will gehen*!", footnotes: ["w. das Angesicht des HERRN zu besänftigen", "℘ 2Chr 11,16; Jes 2,3; Jer 31,6"] },
      { number: 22, text: "Und viele Völker und mächtige Nationen werden kommen, um den HERRN der Heerscharen in Jerusalem zu suchen und den HERRN anzuflehen*.", footnotes: ["℘ Kap. 2,15; 14,16; Mi 4,2; Apg 15,17"] },
      { number: 23, text: "So spricht der HERR der Heerscharen: In jenen Tagen, da werden zehn Männer aus Nationen mit ganz verschiedenen Sprachen* zugreifen, ja, sie werden den Rockzipfel eines jüdischen Mannes ergreifen und sagen: Wir wollen mit euch gehen, denn wir haben gehört, dass Gott mit euch ist*.", footnotes: ["w. Männer aus allerlei Sprachen der Nationen", "℘ Rt 1,16; 2Chr 15,9; Est 8,17; Jes 45,14; 55,5; 1Kor 14,25"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "Ausspruch, Wort des HERRN. Im Land Hadrach und Damaskus* ist sein Ruheplatz — denn dem HERRN gehört das Auge von Aram ebenso wie alle* Stämme Israels —", heading: "Gericht über die Völker und teilweise Rettung", footnotes: ["℘ Jer 49,23; Am 1,3-5", "T.; Mas. T.: denn dem HERRN gehört das Auge des Menschen und alle; möglich ist auch: denn auf den HERRN sind die Augen der Menschen gerichtet und ebenso aller"] },
      { number: 2, text: "und auch in Hamat*, das daran* grenzt, in Tyrus und Sidon* — gewiss, sie sind sehr weise!", footnotes: ["℘ Jer 49,23; Am 1,3-5", "d. i. Damaskus bzw. das Auge von Aram", "℘ Hes 28,21.23"] },
      { number: 3, text: "*Tyrus hat sich zwar eine Festung gebaut, hat Silber wie Staub aufgehäuft und Gold wie Straßenkot*.", footnotes: ["℘ V. 3.4: Jes 23,1-14; Hes 26; 27; 28,1-19; Am 1,9.10", "℘ Jes 23,8"] },
      { number: 4, text: "Doch siehe, der Herr wird es erobern* und seine Streitmacht auf dem Meer schlagen*, und es selbst wird vom Feuer verzehrt.", footnotes: ["w. in Besitz nehmen, o. der Herr wird es enteignen", "o. seinen Reichtum ins Meer stoßen; o. seine Ringmauer ins Meer hauen"] },
      { number: 5, text: "*Aschkelon wird es sehen und sich fürchten, auch Gaza, und wird sehr erzittern, und Ekron, weil seine Hoffnung zuschanden ist*. Und der König wird aus Gaza verschwinden, und Aschkelon wird unbewohnt* sein.", footnotes: ["℘ V. 5-7: Jes 14,28-32; Jer 47; Hes 25,15-17; Am 1,6-8", "℘ Zef 2,4", "o. entvölkert"] },
      { number: 6, text: "Und Mischvolk* wird in Aschdod wohnen. So werde ich den Hochmut der Philister ausrotten.", footnotes: ["w. ein Bastard"] },
      { number: 7, text: "Und ich werde seine blutigen Fleischbrocken aus seinem Mund wegreißen und seine abscheulichen Stücke* zwischen seinen Zähnen hinweg*. So wird auch er * als ein Rest übrig bleiben für unseren Gott und wird sein wie ein Stammverwandter* in Juda und Ekron wie ein Jebusiter*.", footnotes: ["Das sind (durch heidnischen Kult) entweihte Mahlzeiten oder unreine Tiere.", "℘ Jes 65,4", "d. i. der Philister", "o. Anführer, Fürst; w. Tausendmann; ursprünglich für die edomitischen Stammesfürsten gebraucht", "℘ 2Sam 24,18"] },
      { number: 8, text: "Ich aber werde mich für mein Haus als Wache lagern* zum Schutz vor dem, der hindurchzieht und zurückkommt*, dass nie mehr ein Gewalthaber bei ihnen hindurchzieht*, denn jetzt achte ich selbst auf sie*.", footnotes: ["So verstehen LXX und die syr. Üs. den Mas. T. Die Masoreten lesen: für mein Haus vor dem Heer lagern", "℘ Jes 31,5", "℘ 2Kö 19,34; Spr 3,25; Jes 54,14-17", "w. denn jetzt bin ich hinsehend geworden mit meinen eigenen Augen\n℘ Kap. 12,4"] },
      { number: 9, text: "Juble laut, Tochter Zion, jauchze, Tochter Jerusalem*! Siehe, dein König kommt zu dir*: Gerecht und siegreich* ist er, demütig* und auf einem Esel reitend, und zwar auf einem Fohlen*, einem Jungen der Eselin*.", heading: "Der kommende Friedenskönig zur Rettung Israels", footnotes: ["℘ Mi 4,8", "o. dir zugut\n℘ Kap. 2,14; Jes 52,7; Hes 21,32", "o. ein Geretteter. — LXX: ein Retter", "o. niedrig; o. elend. — LXX: sanftmütig\n℘ Mt 11,29", "o. auf einem Eselhengst", "℘ 1Kö 1,38; Mt 21,5; Mk 11,7; Lk 19,35; Joh 12,15"] },
      { number: 10, text: "Und ich rotte die Streitwagen aus Ephraim und die Pferde aus Jerusalem aus, und der Kriegsbogen wird ausgerottet*. Und er verkündet* Frieden den Nationen*. Und seine Herrschaft reicht von Meer zu Meer und vom Strom* bis an die Enden der Erde*.", footnotes: ["℘ Jes 2,4; Hos 2,20; Mi 5,9", "o. gebietet; w. redet", "℘ Mi 5,4", "d. i. der Euphrat", "℘ Ps 72,7.8"] },
      { number: 11, text: "Auch du — um des Blutes deines Bundes willen* lasse ich deine Gefangenen aus der Grube frei, in der kein Wasser ist*.", footnotes: ["℘ Mt 26,27.28; Hebr 13,20", "d. i. wohl eine trockene Zisterne, die wie etwa in 1Mo 37,20 o. Jer 41,7 als Gefängnis benutzt wurde\n℘ Jes 51,14"] },
      { number: 12, text: "Kehrt zur Festung zurück, ihr auf Hoffnung Gefangenen*! Auch heute verkündige ich: Doppeltes erstatte ich dir*.", footnotes: ["℘ Jes 49,9; Jer 31,17", "℘ Jes 61,7"] },
      { number: 13, text: "Ja, ich habe mir Juda als Bogen gespannt, den Köcher mit Ephraim gefüllt*. Ich wecke deine Söhne, Zion, gegen die bewährten Kämpfer Griechenlands* und mache dich wie das Schwert eines Helden*.", footnotes: ["so mit anderer Zeichensetzung; Mas. T.: Ich habe mir Juda gespannt, den Bogen mit Ephraim gefüllt", "T.; Mas. T.: gegen deine Söhne, Griechenland\n℘ Dan 8,21", "℘ Mi 5,7"] },
      { number: 14, text: "Und der HERR wird über ihnen erscheinen, und sein Pfeil fährt aus wie der Blitz*. Und der Herr, HERR stößt ins Horn* und zieht einher in Stürmen des Südens*.", footnotes: ["℘ Ps 18,15", "℘ Joe 4,16", "℘ Hi 37,9"] },
      { number: 15, text: "Der HERR der Heerscharen wird sie beschirmen*; und seine Schleudersteine werden fressen und zu Boden strecken, sie werden Blut trinken wie Wein* und davon voll werden wie die Opferschale, wie die Ecken des Altars.", footnotes: ["℘ Kap. 2,9; 12,8", "so mit einigen griech. Handschr.; Mas. T.: trinken, lärmen wie vom Wein\n℘ Kap. 10,7"] },
      { number: 16, text: "So wird der HERR, ihr Gott, sie an jenem Tag retten als die Herde seines Volkes*. Denn Steine an seinem Diadem sind sie, die über seinem Land funkeln*.", footnotes: ["℘ Hes 34,11.12", "℘ 2Mo 28,9.21; Jes 54,12; 62,3"] },
      { number: 17, text: "Ja, wie anmutig ist es, wie schön ist es! Das Getreide lässt junge Männer gedeihen und der Most Jungfrauen*.", footnotes: ["℘ Ps 144,12.13"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "Erbittet euch von dem HERRN Regen zur Zeit des Spätregens*! Der HERR ist es, der die Wetterwolken macht, *er lässt den Regen regnen*, er gibt einem jeden Brot, Kraut auf dem Feld*.", heading: "Gottes Erbarmen nach dem Gericht", footnotes: ["℘ Hi 29,23; 36,27", "T.; Mas. T.: und Regen des Regengusses gibt er ihnen — einem jeden — Kraut auf dem Feld", "℘ Jer 10,13; Hes 34,26", "T.; Mas. T.: und Regen des Regengusses gibt er ihnen — einem jeden — Kraut auf dem Feld\n℘ Jak 5,7.18"] },
      { number: 2, text: "Denn die Hausgötzen haben Trügerisches geredet*, und die Wahrsager haben Lüge geschaut*; und sie erzählen nichtige Träume, trösten mit Dunst*. Darum mussten sie fortziehen wie Schafe, die elend sind, weil kein Hirte da ist*.", footnotes: ["℘ Jer 10,8; Hab 2,18", "℘ Jes 44,25; Jer 27,9.10", "℘ 5Mo 13,2; Hes 13,6.7", "℘ Hes 34,5.6"] },
      { number: 3, text: "Gegen die Hirten ist mein Zorn entbrannt*, und über die Leitböcke bringe ich Heimsuchung*, denn der HERR der Heerscharen nimmt sich seiner Herde, des Hauses Juda, an* und macht es gleichsam zu seinem Prachtross im Kampf*.", footnotes: ["℘ Jer 23,1.2", "℘ Hes 34,16.17", "w. der HERR der Heerscharen sucht seine Herde, das Haus Juda, heim\n℘ Hes 34,11", "℘ Hi 39,25"] },
      { number: 4, text: "Aus ihm* kommt der Eckstein*, aus ihm der Zeltpflock*, aus ihm der Kriegsbogen, aus ihm wird zugleich jeglicher Gewalthaber hervorkommen*.", footnotes: ["d. h. aus Juda selbst", "℘ Jes 28,16", "℘ Jes 22,23", "o. hinausziehen; d. h. jeder Fremdherrscher wird das Land verlassen"] },
      { number: 5, text: "Und sie werden wie Helden sein, die im Kampf den Feind in den Straßenkot treten*; und sie können kämpfen, denn der HERR ist mit ihnen*, und die Reiter auf den Pferden werden zuschanden*.", footnotes: ["℘ Mal 3,21", "℘ 5Mo 20,1", "℘ Jes 31,1"] },
      { number: 6, text: "Und ich stärke das Haus Juda* und rette das Haus Josef und lasse sie wieder in ihrem Land wohnen*, denn ich habe Erbarmen mit ihnen, und sie werden sein, als hätte ich sie nie verstoßen*. Denn ich bin der HERR, ihr Gott, ich erhöre sie*.", footnotes: ["℘ Jes 41,10", "℘ Mi 5,3", "℘ Jer 30,20", "℘ Kap. 13,9; Hos 14,9"] },
      { number: 7, text: "Und Ephraim wird sein wie ein Held*, und ihr Herz wird sich freuen wie vom Wein*. Und ihre Kinder werden es sehen und sich freuen, ihr Herz wird jubeln in dem HERRN*.", footnotes: ["℘ Kap. 12,8", "℘ Kap. 9,15", "℘ Jes 25,9"] },
      { number: 8, text: "Ich will ihnen pfeifen und sie sammeln, denn ich habe sie erlöst*; und sie werden so zahlreich sein, wie sie einst zahlreich waren*.", footnotes: ["℘ Jes 48,20; Jer 31,10.11", "℘ Jer 30,19; Mi 2,12"] },
      { number: 9, text: "Säe ich sie aber ein unter die Völker* und denken sie dann in den fernen Ländern an mich*, so sollen sie mit ihren Kindern am Leben bleiben und zurückkehren*.", footnotes: ["℘ Hos 2,25", "℘ Jes 64,4; Hes 6,9", "℘ 5Mo 30,1-3"] },
      { number: 10, text: "Und ich lasse sie zurückkehren aus dem Land Ägypten, und aus Assur sammle ich sie* und bringe sie in das Land Gilead und auf den Libanon*, und es* wird für sie nicht ausreichen*.", footnotes: ["℘ Hos 11,11", "℘ Jes 27,13", "d. h. das Land Gilead und der Libanon", "℘ Jes 49,19"] },
      { number: 11, text: "Und sie werden* durch die Meerenge hindurchziehen* — er hat im Meer ja die Wellen geschlagen* —, und alle Tiefen des Stromes* werden versiegen. Und der Hochmut Assurs wird gestürzt*, und das Zepter Ägyptens muss weichen*.", footnotes: ["w. es wird; d. i. das Volk", "T.; Mas. T. viell.: Und die Not (o. Enge) durchschreitet das Meer", "℘ Jes 11,15; 44,27", "d. i. der Nil", "℘ Jes 14,25", "℘ Hes 29,14.15"] },
      { number: 12, text: "So werde ich sie stark machen* in dem HERRN*, und nur in seinem Namen werden sie leben*, spricht der HERR*.", footnotes: ["Andere üs. mit Textänderung: So ist ihre Stärke", "℘ Kap. 12,5; Eph 6,10", "℘ Mi 4,5", "w. werden sie gehen, ist der Ausspruch des HERRN"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "Tu auf, Libanon, deine Tore, dass Feuer deine Zedern fresse*!", footnotes: ["℘ Jer 22,6.7"] },
      { number: 2, text: "Heule, Wacholder, weil die Zeder gefallen ist, weil die Herrlichen verwüstet sind! Heult, Eichen Baschans*, weil der unzugängliche Wald dahingesunken ist!", footnotes: ["℘ Jes 2,13"] },
      { number: 3, text: "Horch, das Geheul der Hirten, weil ihre Herrlichkeit verwüstet ist*! Horch, das Gebrüll der Junglöwen*, denn die Pracht des Jordan* ist verwüstet!", footnotes: ["℘ Jer 25,36", "℘ Hes 19,2.3", "℘ Jer 49,19"] },
      { number: 4, text: "So spricht der HERR, mein Gott: Weide die Schlachtschafe*,", heading: "Gerichtswort über die verantwortungslosen Machthaber", footnotes: ["o. die zur Schlachtung bestimmte Schafherde"] },
      { number: 5, text: "deren Käufer* sie schlachten, ohne es zu büßen*; oder wenn sie sie verkaufen, sagen*: Gepriesen sei der HERR*, ich bin nun reich*! Und keiner von deren Hirten* hat mit ihnen Mitleid*.", footnotes: ["o. Besitzer", "o. ohne sich schuldig zu fühlen\n℘ Jer 50,7", "w. ein jeder sagt", "o. Dank sei dem HERRN", "℘ Hos 12,9; Am 2,6; Offb 3,17", "das sind die Hirten der Käufer bzw. der Besitzer der Schafe", "℘ Hes 34,3.4"] },
      { number: 6, text: "Wahrhaftig, ich werde kein Mitleid haben mit den Bewohnern des Landes*, spricht der HERR*. Und siehe, ich lasse die Menschen, einen jeden, in die Hand seines Nächsten* und in die Hand seines Königs geraten; die werden das Land* in Stücke schlagen, und ich werde sie nicht aus ihrer Hand befreien*.", footnotes: ["o. der Erde\n℘ Hes 9,10", "w. ist der Ausspruch des HERRN", "℘ Jes 3,5", "o. die Erde", "w. herausreißen\n℘ Kla 5,8"] },
      { number: 7, text: "Und ich weidete die Schlachtschafe* der Schafhändler.* Und ich nahm mir zwei Stäbe*: den einen nannte ich »Freundlichkeit«, und den anderen nannte ich »Verbindung«, und ich weidete die Schafe.", footnotes: ["o. die zur Schlachtung bestimmte Schafherde", "so in Anlehnung an LXX; Mas. T.: die Schlachtschafe, fürwahr, die elendesten der Schafe!\n℘ Jes 40,11; Mt 9,12", "℘ Mi 7,14"] },
      { number: 8, text: "Und ich tilgte die drei Hirten* in einem Monat aus. Und meine Seele wurde ungeduldig über sie, und auch ihre Seele wurde meiner überdrüssig*.", footnotes: ["o. drei der Hirten", "℘ Joh 5,16"] },
      { number: 9, text: "Da sagte ich: Ich will euch nicht mehr weiden. Was stirbt, mag sterben, und was verkommt, mag verkommen; und die übrig bleiben, sollen eines des anderen Fleisch fressen*!", footnotes: ["℘ Kap. 13,8; Jes 9,20"] },
      { number: 10, text: "Und ich nahm meinen Stab »Freundlichkeit« und zerbrach ihn, um meinen Bund ungültig zu machen, den ich mit allen Völkern geschlossen hatte." },
      { number: 11, text: "So wurde er an jenem Tag ungültig gemacht. Und es erkannten die Schafhändler*, die auf mich* achteten, dass es des HERRN Wort war*.", footnotes: ["so in Anlehnung an LXX; Mas. T.: Und so erkannten die elendesten der Schafe", "o. die auf mein Zeichen", "℘ Jer 32,8"] },
      { number: 12, text: "Und ich sagte zu ihnen: Wenn es recht ist in euren Augen, gebt mir meinen Lohn, wenn aber nicht, lasst es bleiben! Und sie wogen meinen Lohn ab: dreißig Silberschekel." },
      { number: 13, text: "Da sprach der HERR zu mir: Wirf ihn dem Töpfer* hin, den herrlichen Wert, den ich ihnen wert bin! Und ich nahm die dreißig Silberschekel und warf sie in das Haus des HERRN dem Töpfer* hin*.", footnotes: ["o. dem Einschmelzer", "o. dem Einschmelzer", "℘ Mt 27,9.10"] },
      { number: 14, text: "Dann zerbrach ich meinen zweiten Stab »Verbindung«, um die Bruderschaft zwischen Juda und Israel ungültig zu machen*.", footnotes: ["℘ Hes 37,22"] },
      { number: 15, text: "*Und der HERR sprach zu mir: Nimm dir noch einmal Gerät eines Hirten und verhalte dich wie ein törichter Hirte.", footnotes: ["℘ V. 15-17: Jer 23,1.2; Hes 34,1-10"] },
      { number: 16, text: "Denn siehe, ich lasse einen Hirten im Land aufstehen*: Um die verkommenden Tiere kümmert er sich nicht, das Versprengte* sucht er nicht, und das Zerbrochene heilt er nicht, das Gesunde* versorgt er nicht, aber das Fleisch des Fetten isst er und zerreißt sogar ihre Klauen.", footnotes: ["℘ Dan 11,36", "so in Anlehnung an die alten Üs.; andere legen ein Wort zugrunde, das sich üs. ließe als »das Blökende«; die Bedeutung des hebr. Wortes ist nicht gesichert", "w. das Stehende"] },
      { number: 17, text: "Wehe dem nichtigen Hirten, der die Schafe verlässt*! Das Schwert über seinen Arm und über sein rechtes Auge! Sein Arm verdorre, ja, verdorre, und sein rechtes Auge erlösche, ja, erlösche*!", footnotes: ["℘ Joh 10,12", "w. werde ausdruckslos, ja, ausdruckslos"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "Ausspruch, Wort des HERRN über Israel. Es spricht der HERR, der den Himmel ausspannt* und die Grundmauern der Erde legt* und den Geist des Menschen in seinem Inneren bildet*:", heading: "Jerusalems endzeitliche Rettung", footnotes: ["℘ 1Mo 1,8", "℘ Jes 44,24", "℘ 1Mo 2,7; Jes 57,16"] },
      { number: 2, text: "Siehe, ich mache Jerusalem zu einer Taumelschale* für alle Völker ringsum. Und auch über Juda: Es wird in Bedrängnis geraten zusammen mit Jerusalem*.", footnotes: ["o. zur Schwelle des Strauchelns; so verstehen LXX und Vulg. das Wort", "w. zu Jerusalem hinzu\n℘ Mi 4,14"] },
      { number: 3, text: "Und es wird geschehen an jenem Tag, da mache ich Jerusalem zu einem Stemmstein* für alle Völker; alle, die ihn hochstemmen* wollen, werden sich wund reißen. Und alle Nationen der Erde werden sich gegen es versammeln*.", footnotes: ["d. i. ein Gewicht, das zum Üben im Sport verwendet wurde", "o. aufheben", "℘ Kap. 14,2; Joe 4,2.11.12; Mi 4,11; Offb 11,2"] },
      { number: 4, text: "An jenem Tag, spricht der HERR*, schlage ich alle Pferde mit Scheuwerden und ihre Reiter mit Wahnsinn. Über das Haus Juda aber halte ich meine Augen offen*, während ich alle Pferde der Völker mit Blindheit schlage*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Kap. 9,8; 1Kö 8,29", "℘ 2Kö 6,18"] },
      { number: 5, text: "Und die Fürsten* von Juda werden in ihrem Herzen sagen: *Die Bewohner von Jerusalem sollen Stärke nur in dem HERRN der Heerscharen, ihrem Gott, haben.*", footnotes: ["o. Anführer; w. Tausendmänner; ursprünglich für die edomitischen Stammesfürsten gebraucht", "so mit einer hebr. Handschr. und der aram. Üs.; Mas. T.: Stärke sind mir die Bewohner von Jerusalem in dem HERRN der Heerscharen, ihrem Gott.", "so mit einer hebr. Handschr. und der aram. Üs.; Mas. T.: Stärke sind mir die Bewohner von Jerusalem in dem HERRN der Heerscharen, ihrem Gott.\n℘ Kap. 10,12; Jes 28,5.6; 45,24"] },
      { number: 6, text: "An jenem Tag mache ich die Fürsten* von Juda einem Feuerbecken unter Holzstücken und einer Feuerfackel unter Garben gleich; und sie werden zur Rechten und zur Linken alle Völker ringsum verzehren*. Und immer noch wird Jerusalem* an seiner Stätte bleiben in Jerusalem*.", footnotes: ["o. Anführer; w. Tausendmänner; ursprünglich für die edomitischen Stammesfürsten gebraucht", "℘ Ob 18; Mi 4,13", "d. h. die Einwohnerschaft von Jerusalem", "℘ Kap. 14,10.11"] },
      { number: 7, text: "Der HERR aber wird die Zelte Judas zuerst retten, damit der Stolz des Hauses David und der Stolz der Bewohner von Jerusalem gegenüber Juda nicht zu groß werde." },
      { number: 8, text: "An jenem Tag wird der HERR die Bewohner von Jerusalem beschirmen*; und der Stürzende unter ihnen wird an jenem Tag wie David sein* und das Haus David wie Gott, wie der Engel des HERRN vor ihnen her*.", footnotes: ["℘ Kap. 9,15.16", "℘ Kap. 10,7; Jes 33,24; Joe 4,10", "℘ 2Mo 23,20"] },
      { number: 9, text: "Und es wird geschehen an jenem Tag, da trachte ich danach, alle Nationen zu vernichten, die gegen Jerusalem herankommen*.", footnotes: ["℘ Jes 54,15; Hag 2,22; Offb 20,9"] },
      { number: 10, text: "Aber über das Haus David und über die Bewohnerschaft von Jerusalem gieße ich den Geist der Gnade und des Flehens aus*, und sie werden auf mich blicken*, den sie durchbohrt haben*, und werden über ihn wehklagen, wie man über den einzigen Sohn wehklagt, und werden bitter über ihn weinen, wie man bitter über den Erstgeborenen weint*.", footnotes: ["℘ Kap. 13,9; 1Sam 7,2; Hes 39,29", "Eine Reihe von hebr. Handschr. ändert in: und sie werden auf ihn blicken. — Dem Hebräer erschien es unmöglich, dass Jahwe durchbohrt werden könnte.", "℘ Joh 19,37", "℘ Am 8,10; Mt 24,30; Lk 7,12.13"] },
      { number: 11, text: "An jenem Tag wird die Wehklage in Jerusalem groß sein wie die Wehklage von Hadad-Rimmon in der Ebene von Megiddo*.", footnotes: ["℘ 2Chr 35,22-25; Offb 16,16"] },
      { number: 12, text: "Und wehklagen wird das Land, Sippe um Sippe für sich, die Sippe des Hauses David für sich und ihre Frauen für sich, die Sippe des Hauses Nathan* für sich und ihre Frauen für sich,", footnotes: ["℘ 2Sam 5,14"] },
      { number: 13, text: "die Sippe des Hauses Levi für sich und ihre Frauen für sich, die Sippe der Schimiter* für sich und ihre Frauen für sich,", footnotes: ["℘ 4Mo 3,21"] },
      { number: 14, text: "alle übrigen Sippen, Sippe um Sippe für sich und ihre Frauen für sich*.", footnotes: ["℘ Hes 7,16; Offb 1,7"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "An jenem Tag wird für das Haus David und die Bewohner von Jerusalem eine Quelle geöffnet sein gegen* Sünde und gegen* Befleckung*.", heading: "Ausrottung der Götter und falschen Propheten", footnotes: ["w. in Bezug auf", "w. in Bezug auf", "℘ Jes 12,3; Hes 36,25; Apg 13,38.39; Röm 11,26.27"] },
      { number: 2, text: "Und es wird geschehen an jenem Tag, spricht der HERR* der Heerscharen, da rotte ich die Namen der Götzen aus dem Land aus, dass sie nicht mehr erwähnt werden*; und auch die Propheten und den Geist der Unreinheit werde ich aus dem Land wegschaffen*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ 2Mo 23,13; Jes 2,18; Hos 2,19; Mi 5,12", "℘ 5Mo 18,20; Hes 43,7"] },
      { number: 3, text: "Und es wird geschehen, wenn ein Mann doch noch als Prophet auftritt*, so werden sein Vater und seine Mutter, seine eigenen Eltern, zu ihm sagen: Du darfst nicht am Leben bleiben, denn du hast Lüge geredet im Namen des HERRN! Und sein Vater und seine Mutter, seine eigenen Eltern, werden ihn durchbohren, wenn er als Prophet auftritt*.", footnotes: ["o. weissagt", "o. weissagt\n℘ 5Mo 18,20; Hes 43,7"] },
      { number: 4, text: "Und es wird geschehen an jenem Tag, da werden die Propheten sich schämen*, jeder über seine Vision, dass er als Prophet aufgetreten ist*; nie mehr werden sie einen härenen Mantel* anlegen, um zu lügen*.", footnotes: ["℘ Mi 3,7", "w. bei seinem Weissagen", "℘ 2Kö 1,8", "o. um zu verleugnen; d. h., dass sie Propheten sind"] },
      { number: 5, text: "So einer wird sagen: Ich bin kein Prophet*, ein Mann, der seinen Acker bebaut, bin ich, denn der Ackerbau ist mein Erwerb* von meiner Jugend an.", footnotes: ["℘ Am 7,14", "o. dem Acker galt mein Eifer; beide Üs. nach T.; Mas. T.: ein Mensch kaufte mich"] },
      { number: 6, text: "Sagt man aber zu ihm: Was sind das für Wunden zwischen deinen Händen*?, dann wird er sagen: Sie entstanden, als ich im Haus meiner Freunde geschlagen wurde.", footnotes: ["o. auf deiner Brust\n℘ 1Kö 18,28"] },
      { number: 7, text: "Wach auf, Schwert, gegen meinen Hirten* und gegen den Mann, der mein Gefährte ist*!, spricht der HERR* der Heerscharen. Schlage den Hirten*, dass die Schafe sich zerstreuen*! Und ich werde meine Hand den Kleinen* zuwenden.", heading: "Das Schwertlied: Das neue Volk", footnotes: ["℘ Joh 10,11", "℘ Jes 53,10; Phil 2,6", "w. ist der Ausspruch des HERRN", "2 griech. Üs. lesen: Ich will den Hirten schlagen", "℘ Mt 26,31; Mk 14,27", "o. Geringen. — Das Wort klingt im Hebr. an »Zoar« an, die Stadt, in die Lot sich retten konnte."] },
      { number: 8, text: "Und es wird im ganzen Land geschehen, spricht der HERR*, zwei Teile davon werden ausgerottet, verscheiden*, und nur der dritte Teil davon bleibt übrig*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Kap. 11,9", "℘ Jes 6,13"] },
      { number: 9, text: "Und ich bringe den dritten Teil ins Feuer, läutere sie, wie man das Silber läutert*, und prüfe sie, wie man das Gold prüft*. Der wird meinen Namen anrufen*, und ich werde ihm antworten*, ich werde sagen*: Er ist mein Volk. Und er wird sagen: Der HERR ist mein Gott*.", footnotes: ["℘ Jes 48,10; Jer 9,6; Mal 3,2.3", "℘ Dan 11,35; 1Petr 1,6.7", "℘ Kap. 12,10", "℘ Kap. 10,6; Ps 91,15", "T.; Mas. T.: ich habe gesagt", "℘ Kap. 8,8; Hl 2,16; Jer 31,33; Hes 14,11; Hos 2,25"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "Siehe, ein Tag kommt* für den HERRN, da verteilt man in deiner Mitte dein Plündergut.", heading: "Der Tag des HERRN für Jerusalem und die Völker", footnotes: ["℘ Zef 1,7.14"] },
      { number: 2, text: "Und ich versammle alle Nationen nach Jerusalem zum Krieg*; und die Stadt wird eingenommen und die Häuser werden geplündert. Und die Frauen werden geschändet. Und die Hälfte der Stadt wird in die Gefangenschaft* ausziehen, aber der Rest des Volkes wird nicht aus der Stadt ausgerottet werden*.", footnotes: ["℘ Kap. 12,3; Offb 16,14-16", "w. Wegführung", "℘ Jes 13,16; Kla 5,11"] },
      { number: 3, text: "Dann wird der HERR ausziehen und gegen jene Nationen kämpfen, wie er schon immer gekämpft hat am Tag der Schlacht*.", footnotes: ["℘ Jos 10,10-14; Neh 4,14; Jes 29,7; Offb 19,19"] },
      { number: 4, text: "Und seine Füße werden an jenem Tag auf dem Ölberg stehen, der vor Jerusalem im Osten liegt*; und der Ölberg wird sich von seiner Mitte aus nach Osten und nach Westen spalten zu einem sehr großen Tal, und die eine Hälfte des Berges wird nach Norden und seine andere Hälfte nach Süden weichen*.", footnotes: ["℘ 2Sam 15,30; Hes 11,23; Apg 1,12", "℘ Mi 1,4"] },
      { number: 5, text: "*Und ihr werdet in das Tal meiner Berge fliehen, und das Tal der Berge wird bis Azal* reichen.* Und ihr werdet fliehen, wie ihr vor dem Erdbeben geflohen seid in den Tagen Usijas, des Königs von Juda*. Dann wird der HERR, mein Gott, kommen und alle Heiligen mit ihm*.", footnotes: ["Andere üs. in Anlehnung an alte Üs.: Und das Tal Hinnom wird verstopft sein, denn das Tal Hinnom berührt seine Flanke", "℘ Mi 1,11", "Andere üs. in Anlehnung an alte Üs.: Und das Tal Hinnom wird verstopft sein, denn das Tal Hinnom berührt seine Flanke", "℘ Am 1,1", "so mit LXX und der syr. Üs.; Mas. T.: mit dir\n℘ Mt 25,31; 2Thes 1,7.10; Jud 14"] },
      { number: 6, text: "Und es wird geschehen an jenem Tag, da wird kein Licht sein*, die prächtigen Gestirne ziehen sich zusammen*.", footnotes: ["℘ Joe 2,2", "so mit der Schreibform des Mas. T.; die Leseform ist unübersetzbar; andere üs. in Anlehnung an LXX und die syr. Üs.: an jenem Tag, da wird keine Kälte sein, kein Frost oder Eis"] },
      { number: 7, text: "Dann wird es einen Tag lang — er ist dem HERRN bekannt* — weder Tag noch Nacht werden*; und es wird geschehen, zur Zeit des Abends, da wird Licht werden*.", footnotes: ["℘ Mt 24,36", "℘ Jes 60,20; Offb 21,25", "o. Dann wird ein einziger Tag sein — er ist dem HERRN bekannt —, nicht Tag und Nacht; und es wird geschehen, auch zur Zeit des Abends wird Licht sein."] },
      { number: 8, text: "Und es wird geschehen an jenem Tag, da wird lebendiges Wasser aus Jerusalem fließen*, die eine Hälfte zum östlichen Meer und die andere Hälfte zum hinteren Meer; im Sommer wie im Winter wird es so geschehen.", footnotes: ["℘ Offb 22,1"] },
      { number: 9, text: "Und der HERR wird König sein über die ganze Erde*; an jenem Tag wird der HERR einzig sein und sein Name einzig*.", footnotes: ["℘ Ps 97,1; Jes 54,5; Mal 1,14; Offb 11,15", "℘ 5Mo 6,4"] },
      { number: 10, text: "Das ganze Land wird sich verwandeln, so dass es wird wie die Niederung* von Geba* bis Rimmon* im Süden von Jerusalem. Jerusalem selbst aber* wird erhaben sein* und an seiner Stätte bleiben, vom Tor Benjamin* bis zur Stelle des ersten Tores, bis zum Ecktor*, und vom Turm* Hananel* bis zu den Kelterkufen des Königs.", footnotes: ["hebr. Araba; d. i. die Niederung, die zu beiden Seiten des Jordan und des Toten Meeres liegt", "℘ Jos 21,17", "℘ Jos 15,32", "w. Es aber", "℘ Kap. 8,3; Mi 4,1", "℘ Jer 37,13", "℘ 2Chr 26,9", "so mit vielen hebr. Handschr.; Mas. T.: und zum Turm", "℘ Neh 3,1"] },
      { number: 11, text: "Und man wird darin wohnen. Und einen Bann wird es nicht mehr geben*, und Jerusalem wird in Sicherheit wohnen*.", footnotes: ["℘ Jer 31,40; Offb 22,3", "℘ Kap. 12,6; 5Mo 33,28; Jer 23,6"] },
      { number: 12, text: "Und dies wird die Plage sein, mit der der HERR alle Völker plagen wird, die gegen Jerusalem in den Krieg gezogen sind*: Er lässt jedem sein Fleisch verwesen*, während er noch auf seinen Füßen steht, und seine Augen werden verwesen in ihren Höhlen, und seine Zunge wird in seinem Mund verwesen.", footnotes: ["℘ Kap. 1,15; 2,4", "℘ Hes 38,22"] },
      { number: 13, text: "Und es wird geschehen an jenem Tag, da wird eine große Verwirrung von dem HERRN unter ihnen entstehen, so dass einer des anderen Hand packen und sich seine Hand gegen die Hand seines Nächsten erheben wird*.", footnotes: ["℘ Ri 7,22; Hes 38,21"] },
      { number: 14, text: "Und auch Juda wird gegen* Jerusalem kämpfen. Da wird dann der Reichtum aller Nationen ringsum eingesammelt werden: Gold und Silber und Kleider in großer Menge*.", footnotes: ["o. in", "℘ 2Chr 20,25; Hes 39,10"] },
      { number: 15, text: "Und ebenso, gleich dieser Plage, wird auch die Plage für die Pferde, die Maultiere, die Kamele und die Esel sein sowie für alle Tiere, die in jenen Heerlagern sind." },
      { number: 16, text: "Und es wird geschehen: Alle Übriggebliebenen von allen Nationen, die gegen Jerusalem gekommen sind, die werden Jahr für Jahr hinaufziehen, um den König, den HERRN der Heerscharen, anzubeten* und das Laubhüttenfest zu feiern*.", footnotes: ["w. um sich niederzuwerfen vor dem König, dem HERRN der Heerscharen\n℘ Kap. 8,22", "℘ 3Mo 23,34; Jes 66,23"] },
      { number: 17, text: "Und es wird geschehen, wenn eines von den Geschlechtern* der Erde nicht nach Jerusalem hinaufziehen wird, um den König, den HERRN der Heerscharen, anzubeten*; über diese wird kein Regen kommen*.", footnotes: ["w. Sippen", "w. um sich niederzuwerfen vor dem König, dem HERRN der Heerscharen", "℘ 1Kö 8,35; Ps 2,10-12"] },
      { number: 18, text: "Und wenn das Geschlecht* Ägyptens nicht hinaufzieht und nicht kommt, *dann wird der Regen auch über dieses nicht kommen*. Das wird die Plage sein, mit der* der HERR die Nationen plagen wird, die nicht hinaufziehen werden, das Laubhüttenfest zu feiern*.", footnotes: ["w. die Sippe", "Andere üs. mit Textänderung: so wird über sie die Plage kommen, mit der", "℘ Jes 60,12; Mi 5,8", "Andere üs. mit Textänderung: so wird über sie die Plage kommen, mit der", "℘ 3Mo 23,34; Jes 66,23"] },
      { number: 19, text: "Das wird die Strafe für Ägypten und die Strafe für alle Nationen sein, die nicht hinaufziehen, das Laubhüttenfest zu feiern*.", footnotes: ["℘ 3Mo 23,34; Jes 66,23"] },
      { number: 20, text: "An jenem Tag wird auf den Schellen der Pferde stehen: »Heilig dem HERRN«*. Und die Kochtöpfe im Haus des HERRN* werden wie die Opferschalen vor dem Altar sein*;", footnotes: ["℘ Kap. 8,3; 2Mo 28,36", "Andere nehmen einen Schreibfehler an und lesen: im Haus Juda", "℘ 1Kö 7,50"] },
      { number: 21, text: "und jeder Kochtopf in Jerusalem und in Juda wird dem HERRN der Heerscharen heilig sein; und alle Opfernden werden kommen und von ihnen nehmen und darin kochen. An jenem Tag wird es keinen Viehhändler mehr geben im Haus des HERRN der Heerscharen*.", footnotes: ["℘ Hes 44,9; Zef 1,11; Offb 21,27"] },
    ]},
  ]
};
